// The keep28 cleanup policy (approved by the owner) keeps exactly ONE period per
// stream: the stream's best 14 local days ±7 days, i.e. 28 local days. Every
// NAS file whose bounds, and all of whose source clips' bounds, lie entirely
// outside that period is cleanup-eligible, including files behind published
// deliveries. Nothing inside the period can be admitted, observed as
// would_delete, or deleted. The selection is generated by
// ~/stoarama-r2-select/select.py and embedded byte-for-byte; the binary refuses
// any cleanup decision if the embedded bytes differ from the pinned SHA.
//
//go:embed nas_cleanup_keep28_policy.json
var cleanupKeep28PolicyJSON []byte

// cleanupPolicySHA also binds every plan (nas_cleanup_plans.report_sha256).
// Plans admitted under any other policy are never leased, observed as
// would_delete, resumed, or enabled; retire them with retire-superseded.
const cleanupPolicySHA = "060aa7070c7909d78013415f83b76bd0c027a885caf91c67c8b709ac1f4b5811"
const cleanupPolicyStreams = 109
const cleanupKeepDays = 28

type cleanupKeepWindow struct {
	StreamID    int64  `json:"stream_id"`
	Timezone    string `json:"tz"`
	BestStart   string `json:"best_start"`
	KeepStart   string `json:"keep_start"`
	KeepEndExcl string `json:"keep_end_excl"`
	StartUTC    string `json:"keep_start_utc"`
	EndUTC      string `json:"keep_end_utc"`
	start, end  time.Time
}
type nasCleanupPolicy struct {
	SHA     string
	Streams map[int64]cleanupKeepWindow
}

const cleanupSourceMetadataSQL = `SELECT jsonb_agg(jsonb_build_array(c.id,c.recording_id,r.stream_id,(extract(epoch FROM c.clip_start_at)*1000000)::bigint,(extract(epoch FROM c.clip_end_at)*1000000)::bigint,coalesce(nullif(s.local_timezone,''),r.cron_timezone),c.size_bytes,lower(c.sha256),c.object_key,c.display_path,c.bucket) ORDER BY c.id) FROM recording_clips c JOIN recordings r ON r.id=c.recording_id JOIN streams s ON s.id=r.stream_id WHERE r.account_id=47 AND c.id=ANY($1)`

// parseCleanupPolicy validates the embedded selection: exact SHA, exactly 109
// distinct streams, each with exactly one window of 28 local days centred on
// the best-14 start (keep = [best-7d, best+21d)), and UTC bounds that are the
// local midnights of those dates in the stream's canonical timezone.
func parseCleanupPolicy(raw []byte, sha string, streams int) (*nasCleanupPolicy, error) {
	if cleanupSHA(raw) != sha {
		return nil, errors.New("cleanup policy hash differs")
	}
	var rows []cleanupKeepWindow
	if err := json.Unmarshal(raw, &rows); err != nil || len(rows) != streams {
		return nil, errors.New("incomplete cleanup policy")
	}
	p := &nasCleanupPolicy{SHA: sha, Streams: map[int64]cleanupKeepWindow{}}
	for _, w := range rows {
		if w.StreamID <= 0 || w.Timezone == "" {
			return nil, errors.New("invalid cleanup policy stream")
		}
		if _, dup := p.Streams[w.StreamID]; dup {
			return nil, errors.New("cleanup policy has more than one window for a stream")
		}
		loc, err := time.LoadLocation(w.Timezone)
		if err != nil {
			return nil, errors.New("cleanup policy timezone unavailable")
		}
		best, e1 := time.ParseInLocation(time.DateOnly, w.BestStart, loc)
		ks, e2 := time.ParseInLocation(time.DateOnly, w.KeepStart, loc)
		ke, e3 := time.ParseInLocation(time.DateOnly, w.KeepEndExcl, loc)
		su, e4 := time.Parse(time.RFC3339, w.StartUTC)
		eu, e5 := time.Parse(time.RFC3339, w.EndUTC)
		if errors.Join(e1, e2, e3, e4, e5) != nil {
			return nil, errors.New("invalid cleanup policy dates")
		}
		if !ks.Equal(best.AddDate(0, 0, -7)) || !ke.Equal(best.AddDate(0, 0, cleanupKeepDays-7)) || !ke.Equal(ks.AddDate(0, 0, cleanupKeepDays)) || !su.Equal(ks) || !eu.Equal(ke) || ks.Year() < 2020 || ke.Year() >= 2028 {
			return nil, errors.New("cleanup policy window is not 28 local days around best14")
		}
		w.start, w.end = ks.UTC(), ke.UTC()
		p.Streams[w.StreamID] = w
	}
	return p, nil
}

var cleanupEmbeddedPolicy = sync.OnceValues(func() (*nasCleanupPolicy, error) {
	return parseCleanupPolicy(cleanupKeep28PolicyJSON, cleanupPolicySHA, cleanupPolicyStreams)
})

func (s *Server) cleanupPolicy(context.Context) (*nasCleanupPolicy, error) {
	return cleanupEmbeddedPolicy()
}

// outside is true only for a valid, nonempty media interval of a stream that
// has a pinned window and that does not intersect [keep_start, keep_end).
// Unknown streams and invalid bounds are always KEEP.
func (p *nasCleanupPolicy) outside(stream int64, a, b time.Time) bool {
	if a.IsZero() || !b.After(a) || a.Year() < 2020 || b.Year() >= 2028 {
		return false
	}
	w, ok := p.Streams[stream]
	if !ok {
		return false
	}
	return !(a.Before(w.end) && b.After(w.start))
}

// Replays select.py for one stream: per local day, the union of seconds covered
// by clips that are not collation-quarantined (no R2 availability requirement);
// candidates run from the first recorded day-13 to the last recorded day; the
// best 14-day sum wins and ties go to the earliest start. Returns the winning
// local date (empty when the stream has no valid clips). A different winner than
// the pinned best_start keeps the whole stream (fail closed).
// cleanupRankingsInputSQL selects exactly the rows the replay scores: every
// valid clip interval of the stream with its canonical timezone and whether it
// is collation-quarantined. The replay is a pure function of this multiset.
const cleanupRankingsInputSQL = `WITH r AS (
 SELECT r.id,coalesce(nullif(s.local_timezone,''),r.cron_timezone) tz FROM recordings r JOIN streams s ON s.id=r.stream_id WHERE r.account_id=47 AND r.stream_id=$1
), excluded AS (
 SELECT DISTINCT (p.item->'clip'->>'clip_id')::bigint clip_id FROM recording_collation_hours h JOIN r ON r.id=h.recording_id CROSS JOIN LATERAL jsonb_array_elements(h.manifest->'clips') p(item) WHERE h.excluded_clip_count>0 AND p.item->>'disposition'='quarantined'
), c AS (
 SELECT c.clip_start_at a,c.clip_end_at b,r.tz,e.clip_id IS NULL clean FROM recording_clips c JOIN r ON r.id=c.recording_id LEFT JOIN excluded e ON e.clip_id=c.id
 WHERE c.clip_end_at>c.clip_start_at AND c.clip_start_at>='2020-01-01' AND c.clip_end_at<'2028-01-01'
)`

const cleanupRankingsScoresSQL = `, pieces AS (
 SELECT d::date local_date,tstzrange(greatest(c.a,d AT TIME ZONE c.tz),least(c.b,(d+interval '1 day') AT TIME ZONE c.tz),'[)') span,clean FROM c CROSS JOIN LATERAL generate_series(date_trunc('day',a AT TIME ZONE tz),date_trunc('day',(b-interval '1 microsecond') AT TIME ZONE tz),interval '1 day') d
), unions AS (
 SELECT local_date,range_agg(span) FILTER(WHERE clean) clean_spans FROM pieces GROUP BY local_date
), daily AS (
 SELECT local_date,(SELECT coalesce(sum(extract(epoch FROM upper(x)-lower(x))),0) FROM unnest(clean_spans) x) seconds FROM unions
), candidates AS (
 SELECT d::date local_date FROM generate_series((SELECT min(local_date)-13 FROM daily)::timestamp,(SELECT max(local_date) FROM daily)::timestamp,interval '1 day') d
), scores AS (
 SELECT candidates.local_date,(SELECT coalesce(sum(seconds),0) FROM daily WHERE daily.local_date>=candidates.local_date AND daily.local_date<candidates.local_date+14) score FROM candidates
)`

const cleanupRankingsWinnerExpr = `coalesce((SELECT local_date::text FROM scores ORDER BY score DESC,local_date LIMIT 1),'')`

// cleanupRankingsFingerprintExpr is a collision-resistant digest of the
// replay's complete input multiset (count, exact microsecond bounds, timezone
// and quarantine flag of every scored or range-extending clip).
const cleanupRankingsFingerprintExpr = `(SELECT count(*)::text||':'||encode(sha256(convert_to(coalesce(string_agg(extract(epoch FROM c.a)::text||','||extract(epoch FROM c.b)::text||','||coalesce(c.tz,'~null~')||','||c.clean::text,';' ORDER BY c.a,c.b,c.tz,c.clean),''),'UTF8')),'hex') FROM c)`

const cleanupCurrentRankingsSQL = cleanupRankingsInputSQL + cleanupRankingsScoresSQL + ` SELECT ` + cleanupRankingsWinnerExpr

// One statement, one snapshot: the winner and the fingerprint of exactly the
// rows it was computed from.
const cleanupRankingsWithFingerprintSQL = cleanupRankingsInputSQL + cleanupRankingsScoresSQL + ` SELECT ` + cleanupRankingsWinnerExpr + `,` + cleanupRankingsFingerprintExpr

const cleanupRankingsFingerprintSQL = cleanupRankingsInputSQL + ` SELECT ` + cleanupRankingsFingerprintExpr

func (s *Server) cleanupCurrentPolicy(ctx context.Context, q interface {
	QueryRow(context.Context, string, ...any) pgx.Row
}, i nasCleanupItem) error {
	return s.cleanupCurrentPolicyMode(ctx, q, i, false, nil)
}

// cleanupCurrentPolicyMode is the per-file KEEP decision used at every
// observation (dry run and enabled). It requires: the file's directory is a
// reviewed folder owned only by the file's stream; the file and every source
// clip lie outside the stream's single keep28 window; the canonical timezone
// and pinned source manifest are unchanged; and a live replay of the best-14
// selection still yields the pinned best_start. Publication, collation and
// joined-snapshot references no longer protect files outside the window.
func (s *Server) cleanupCurrentPolicyMode(ctx context.Context, q interface {
	QueryRow(context.Context, string, ...any) pgx.Row
}, i nasCleanupItem, dryRun bool, stages map[string]any) error {
	return s.cleanupCurrentPolicyCheck(ctx, q, i, dryRun, stages, nil)
}

// cleanupRankingsUnchanged reports whether the live replay inputs of a stream
// are byte-identical (by fingerprint) to the inputs of a full replay that
// already yielded the pinned best_start for this plan's execution, or a
// version-validated cached replay (maximum age 60 seconds) proves it. Only then
// may the per-file check skip the replay. Errors fail closed; an unavailable
// verdict requires a full replay under the same source fence.
type cleanupRankingsUnchanged func(stream int64, pinnedBest string) (bool, error)

// cleanupCurrentPolicyCheck is cleanupCurrentPolicyMode with an optional
// execution fast path for the best-14 replay (see cleanupRankingsUnchanged).
// Every other check runs per file exactly as before.
func (s *Server) cleanupCurrentPolicyCheck(ctx context.Context, q interface {
	QueryRow(context.Context, string, ...any) pgx.Row
}, i nasCleanupItem, dryRun bool, stages map[string]any, unchanged cleanupRankingsUnchanged) error {
	report, err := s.cleanupReport(ctx)
	if err != nil || !report.permits(i) {
		return errors.New("reviewed folder ownership unavailable")
	}
	policy, err := s.cleanupPolicy(ctx)
	if err != nil {
		return err
	}
	window, ok := policy.Streams[i.StreamID]
	if !ok {
		return errors.New("stream has no pinned keep window; KEEP")
	}
	if window.Timezone != i.Timezone {
		return errors.New("canonical timezone changed")
	}
	if !policy.outside(i.StreamID, i.StartAt, i.EndAt) {
		return errors.New("current media bounds overlap KEEP")
	}
	rankingStarted := time.Now()
	var best []byte
	var rankingsAt time.Time
	verified := false
	if !dryRun && unchanged != nil {
		verified, err = unchanged(i.StreamID, window.BestStart)
		if err != nil {
			return err
		}
	}
	if verified {
		best, rankingsAt = []byte(window.BestStart), rankingStarted.UTC()
		if stages != nil {
			stages["rankings_mode"] = "fingerprint"
			if stages["rankings_cache"] == "replay" {
				stages["rankings_mode"] = "replay"
			}
		}
	} else {
		best, rankingsAt, err = s.cleanupRankings(ctx, q, i.StreamID, dryRun)
		if stages != nil {
			stages["rankings_mode"] = "replay"
		}
	}
	if stages != nil {
		stages["rankings_ms"] = time.Since(rankingStarted).Milliseconds()
	}
	if err != nil {
		return err
	}
	if stages != nil {
		stages["rankings_snapshot_at"] = rankingsAt
		stages["rankings_advisory"] = dryRun
	}
	if string(best) != window.BestStart {
		return errors.New("current best14 selection changed; KEEP until reviewed")
	}
	// SourceManifestSHA pins dates, source membership, canonical timezone and
	// exact catalog source identity. Every source must also be outside KEEP.
	var raw []byte
	sourceStarted := time.Now()
	err = q.QueryRow(ctx, cleanupSourceMetadataSQL, i.SourceIDs).Scan(&raw)
	if stages != nil {
		stages["source_metadata_ms"] = time.Since(sourceStarted).Milliseconds()
	}
	if err != nil || cleanupSHA(raw) != i.SourceManifestSHA {
		return errors.New("source manifest changed")
	}
	var sources [][]json.RawMessage
	if json.Unmarshal(raw, &sources) != nil || len(sources) != len(i.SourceIDs) {
		return errors.New("incomplete source metadata")
	}
	for _, row := range sources {
		if len(row) != 11 {
			return errors.New("invalid source metadata")
		}
		var sid, a, b int64
		var tz, bucket string
		if json.Unmarshal(row[2], &sid) != nil || json.Unmarshal(row[3], &a) != nil || json.Unmarshal(row[4], &b) != nil || json.Unmarshal(row[5], &tz) != nil || json.Unmarshal(row[10], &bucket) != nil || bucket != i.Bucket || sid != i.StreamID || tz != i.Timezone || !policy.outside(sid, time.UnixMicro(a), time.UnixMicro(b)) {
			return errors.New("current source intersects KEEP or is unknown")
		}
	}
	return nil
}
